// 原本域writer到实际Common cache/history绑定；callback为精确隔离effect匹配，非World回执验收。
#define POLITICAL_OFFICE_RESIGNATION_RULES_FIXTURE_ONLY
#include "political_office_resignation_rules_test.cpp"
#include "resident/domains/politics/office_resignations/political_office_resignation_receipts.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
namespace {
struct ResignationReceiptFixture:ResignationRulesFixture {
 StableId commit(const StableId& actor,const PoliticalOfficeResignationCommand& command,Integer request){auto before=resignations;auto id=submit(actor,command);auto kind=political_office_resignation_command_kind(command);check(take(political_office_resignation_new_player_source(before,resignations,actor,kind,common.tick()))==id,"only actual new resignation source selected");auto result=std::make_shared<CommitResult>();result->ok=true;result->kind=kind;result->tick=common.tick();result->revision=++common.state().identity.revision;result->result_id=take(common.next_id("result"));common.state().request_sequences.set(actor,request);common.state().results.insert(actor+":"+std::to_string(request),result);common.state().history.push_back({result->tick,kind,actor,result->result_id,{}});check(bind_political_office_resignation_player_result(common,resignations,id,actor,request,*result,[&](const CommitResult&,const StableId& fact,const StableId& office){const auto* row=resignations.answers.find(id);return fact==id&&office==(row?row->office_change_fact_id:StableId{});}).ok,"actual cache object binds source and original Office result");return id;}
 Status valid(){return validate_political_office_resignation_player_results(common,resignations,[&](const CommitResult&,const StableId& fact,const StableId& office){const auto* row=resignations.answers.find(fact);return office==(row?row->office_change_fact_id:StableId{});});}
};
}
int main(){try{
 ResignationReceiptFixture f;auto first=f.commit("candidate",PoliticalRequestOfficeResignation{"ordinary",0,0},1);f.commit("leader",f.answer(first,false),1);auto second=f.commit("candidate",PoliticalRequestOfficeResignation{"ordinary",0,0},2);auto final=f.commit("leader",f.answer(second,true),2);check(f.valid().ok,"request/refusal/new request/approved release each has exact actual result");auto saved=f.resignations;auto common=f.common.state();auto last=*f.common.state().results.find("leader:2");f.common.state().results={};f.common.state().results.insert("leader:2",last);f.common.state().history.erase(f.common.state().history.begin(),f.common.state().history.end()-1);check(f.valid().ok,"first retained result remains bound after earlier cache eviction");auto office=f.resignations.answers.find(final)->office_change_fact_id;f.resignations.answers.erase(final);f.common.state().facts.erase(final);f.common.state().facts.erase(office);check(!f.valid().ok,"deleting latest source cannot rebind retained result to older refusal");f.resignations=saved;f.common.state()=common;
 auto value=encode_political_office_resignation_state(f.resignations);auto decoded=take(decode_political_office_resignation_state(value));check(compare_boundary(value,encode_political_office_resignation_state(decoded)).exact(),"new source and result JSON exact");CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);take(visit_political_office_resignation_checkpoint(writer,decoded));take(writer.finish());const auto& fixed=bytes;CodecVisitor reader(fixed);PoliticalOfficeResignationState restored;take(visit_political_office_resignation_checkpoint(reader,restored));take(reader.finish());check(compare_boundary(value,encode_political_office_resignation_state(restored)).exact(),"independent binary section exact");
 f.resignations.answers.find(final)->player_receipt.reset();check(!f.valid().ok,"unbound source is not an implicit NPC exception");auto clone=*last;check(!bind_political_office_resignation_player_result(f.common,f.resignations,final,"leader",2,clone,[](const auto&,const auto&,const auto&){return true;}).ok,"copy of real result cannot replace actual cache object");check(bind_political_office_resignation_player_result(f.common,f.resignations,final,"leader",2,*last,[](const auto&,const auto&,const auto&){return true;}).ok,"exact pending source binds only actual result");
 const auto old=f.resignations.answers.find(final)->player_receipt->result_id;auto number=take(f.common.next_id("witness"));auto record=*f.resignations.answers.find(final)->player_receipt;record.result_id="result:"+number.substr(number.find(':')+1);f.resignations.answers.find(final)->player_receipt=record;take(f.common.append_fact({number,"fixture_witness","fixture"}));f.common.state().results={};f.common.state().history.clear();check(!f.valid().ok,"permanent result allocation cannot collide with another actual fact after full cache eviction");f.resignations.answers.find(final)->player_receipt->result_id=old;
 for(const PoliticalOfficeResignationCommand& command:std::vector<PoliticalOfficeResignationCommand>{PoliticalRequestOfficeResignation{"ordinary",0,0},f.answer(second),PoliticalWithdrawOfficeResignation{second}}){auto kind=political_office_resignation_command_kind(command);auto raw=encode_political_office_resignation_command(command);check(compare_boundary(raw,encode_political_office_resignation_command(take(decode_political_office_resignation_command(kind,raw)))).exact(),"three strict caller choices roundtrip");}
 std::cout<<checks<<" resignation actual-source binding checks; no World run\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
